    "是否确认删除产品制程物料BOM编号为{v}的数据项？": "هل أنت متأكد من حذف عنصر البيانات من مادة عملية المنتج رقم BOM {v}؟",
    "是否确认删除产品制程编号为{v}的数据项？": "هل أنت متأكد من أنك تريد حذف عنصر البيانات مع رقم عملية المنتج {v}؟",
    "是否确认删除产品销售出库行编号为{v}的数据项？": "هل أنت متأكد من أنك تريد حذف عنصر البيانات مع رقم خط خروج مبيعات المنتج {v}؟",
